static int[] twoSumSorted(int[] nums, int target) {
    int left = 0, right = nums.length - 1;
    while (left < right) {
        int sum = nums[left] + nums[right];
        if (sum == target) return new int[]{left, right};
        if (sum < target) left++;
        else right--;
    }
    return new int[]{-1, -1};
}

static int[] twoSum(int[] nums, int target) {
    Map<Integer, Integer> seen = new HashMap<>();
    for (int i = 0; i < nums.length; i++) {
        Integer j = seen.get(target - nums[i]);
        if (j != null) return new int[]{j, i};
        seen.put(nums[i], i);
    }
    return new int[]{-1, -1};
}

static int maxSumWindow(int[] nums, int k) {
    if (k > nums.length) return 0;
    int window = 0;
    for (int i = 0; i < k; i++) window += nums[i];
    int best = window;
    for (int right = k; right < nums.length; right++) {
        window += nums[right] - nums[right - k];
        best = Math.max(best, window);
    }
    return best;
}

static int longestUniqueSubstring(String s) {
    Set<Character> seen = new HashSet<>();
    int left = 0, best = 0;
    for (int right = 0; right < s.length(); right++) {
        while (seen.contains(s.charAt(right))) {
            seen.remove(s.charAt(left));
            left++;
        }
        seen.add(s.charAt(right));
        best = Math.max(best, right - left + 1);
    }
    return best;
}

static int[] prefixSums(int[] nums) {
    int[] pre = new int[nums.length + 1];
    for (int i = 0; i < nums.length; i++) pre[i + 1] = pre[i] + nums[i];
    return pre;
}

static int subarraySumEqualsK(int[] nums, int k) {
    Map<Integer, Integer> counts = new HashMap<>();
    counts.put(0, 1);
    int running = 0, total = 0;
    for (int x : nums) {
        running += x;
        total += counts.getOrDefault(running - k, 0);
        counts.merge(running, 1, Integer::sum);
    }
    return total;
}

static int kadane(int[] nums) {
    int best = nums[0], current = nums[0];
    for (int i = 1; i < nums.length; i++) {
        current = Math.max(nums[i], current + nums[i]);
        best = Math.max(best, current);
    }
    return best;
}

static void reverseRange(int[] nums, int left, int right) {
    while (left < right) {
        int t = nums[left];
        nums[left++] = nums[right];
        nums[right--] = t;
    }
}

static <T> Map<T, Integer> frequency(List<T> items) {
