static int binarySearch(int[] nums, int target) {
    int left = 0, right = nums.length - 1;
    while (left <= right) {                      // <= : left==right is still a candidate
        int mid = left + (right - left) / 2;     // overflow-safe
        if (nums[mid] == target) return mid;
        if (nums[mid] < target) left = mid + 1;
        else right = mid - 1;
    }
    return -1;
}

static int lowerBound(int[] nums, int target) {
    int left = 0, right = nums.length;
    while (left < right) {                       // < : right is exclusive here
        int mid = left + (right - left) / 2;
        if (nums[mid] < target) left = mid + 1;
        else right = mid;
    }
    return left;
}

static int upperBound(int[] nums, int target) {
    int left = 0, right = nums.length;
    while (left < right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] <= target) left = mid + 1;
        else right = mid;
    }
    return left;
}

static int binarySearchAnswer(int lo, int hi, java.util.function.IntPredicate feasible) {
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (feasible.test(mid)) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}

