static int bfsGrid(char[][] grid, int sr, int sc, boolean[][] visited, char passable) {
    if (!inBounds(sr, sc, grid) || visited[sr][sc] || grid[sr][sc] != passable) return 0;
    Queue<int[]> queue = new ArrayDeque<>();
    queue.offer(new int[]{sr, sc});
    visited[sr][sc] = true;
    int count = 0;
    while (!queue.isEmpty()) {
        int[] cell = queue.poll();
        count++;
        for (int[] d : DIRS4) {
            int nr = cell[0] + d[0], nc = cell[1] + d[1];
            if (inBounds(nr, nc, grid) && !visited[nr][nc] && grid[nr][nc] == passable) {
                visited[nr][nc] = true;
                queue.offer(new int[]{nr, nc});
            }
        }
    }
    return count;
}

static int countIslands(char[][] grid) {
    boolean[][] visited = new boolean[grid.length][grid[0].length];
    int count = 0;
    for (int r = 0; r < grid.length; r++) {
        for (int c = 0; c < grid[0].length; c++) {
            if (grid[r][c] == '1' && !visited[r][c]) {
                bfsGrid(grid, r, c, visited, '1');
                count++;
            }
        }
    }
    return count;
}

static Map<Integer, List<Integer>> buildGraph(int[][] edges, boolean directed) {
    Map<Integer, List<Integer>> graph = new HashMap<>();
    for (int[] e : edges) {
        graph.computeIfAbsent(e[0], k -> new ArrayList<>()).add(e[1]);
        if (!directed) graph.computeIfAbsent(e[1], k -> new ArrayList<>()).add(e[0]);
    }
