}

static Map<Integer, Integer> bfsShortest(Map<Integer, List<Integer>> graph, int start) {
    Map<Integer, Integer> dist = new HashMap<>();
    dist.put(start, 0);
    Queue<Integer> queue = new ArrayDeque<>();
    queue.offer(start);
    while (!queue.isEmpty()) {
        int node = queue.poll();
        for (int next : graph.getOrDefault(node, List.of())) {
            if (!dist.containsKey(next)) {
                dist.put(next, dist.get(node) + 1);
                queue.offer(next);
            }
        }
    }
    return dist;
}

static List<Integer> dfsIterative(Map<Integer, List<Integer>> graph, int start) {
    List<Integer> order = new ArrayList<>();
    Set<Integer> seen = new HashSet<>();
    Deque<Integer> stack = new ArrayDeque<>();
    stack.push(start);
    seen.add(start);
    while (!stack.isEmpty()) {
        int node = stack.pop();
        order.add(node);
        for (int next : graph.getOrDefault(node, List.of())) {
            if (seen.add(next)) stack.push(next);
        }
    }
    return order;
}

static List<Integer> topoSort(int numNodes, int[][] edges) {
    Map<Integer, List<Integer>> graph = new HashMap<>();
    int[] indeg = new int[numNodes];
    for (int[] e : edges) {                      // e[0] must come before e[1]
        graph.computeIfAbsent(e[0], k -> new ArrayList<>()).add(e[1]);
        indeg[e[1]]++;
    }
    Queue<Integer> queue = new ArrayDeque<>();
    for (int n = 0; n < numNodes; n++) if (indeg[n] == 0) queue.offer(n);

    List<Integer> order = new ArrayList<>();
    while (!queue.isEmpty()) {
        int node = queue.poll();
        order.add(node);
        for (int next : graph.getOrDefault(node, List.of())) {
            if (--indeg[next] == 0) queue.offer(next);
        }
    }
    return order.size() == numNodes ? order : new ArrayList<>();
}

static Map<Integer, Integer> dijkstra(Map<Integer, List<int[]>> graph, int start) {
    Map<Integer, Integer> dist = new HashMap<>();
    dist.put(start, 0);
    PriorityQueue<int[]> heap = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
    heap.offer(new int[]{0, start});
    while (!heap.isEmpty()) {
        int[] top = heap.poll();
        int d = top[0], node = top[1];
        if (d > dist.getOrDefault(node, Integer.MAX_VALUE)) continue;   // stale entry
        for (int[] edge : graph.getOrDefault(node, List.of())) {
            int next = edge[0], nd = d + edge[1];
            if (nd < dist.getOrDefault(next, Integer.MAX_VALUE)) {
                dist.put(next, nd);
                heap.offer(new int[]{nd, next});
            }
        }
    }
    return dist;
}

static class UnionFind {
    private final int[] parent;
    private final int[] size;
    int components;

    UnionFind(int n) {
        parent = new int[n];
        size = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            size[i] = 1;
        }
        components = n;
    }

    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];   // path halving
            x = parent[x];
        }
        return x;
    }

    boolean union(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return false;
        if (size[ra] < size[rb]) { int t = ra; ra = rb; rb = t; }
        parent[rb] = ra;
        size[ra] += size[rb];
        components--;
        return true;
    }

    boolean connected(int a, int b) {
        return find(a) == find(b);
    }
}

static int[][] mergeIntervals(int[][] intervals) {
    if (intervals.length == 0) return new int[0][];
    int[][] sorted = Arrays.copyOf(intervals, intervals.length);
    Arrays.sort(sorted, Comparator.comparingInt(a -> a[0]));

    List<int[]> merged = new ArrayList<>();
    merged.add(new int[]{sorted[0][0], sorted[0][1]});
    for (int i = 1; i < sorted.length; i++) {
        int[] last = merged.get(merged.size() - 1);
        if (sorted[i][0] <= last[1]) {
            last[1] = Math.max(last[1], sorted[i][1]);
        } else {
            merged.add(new int[]{sorted[i][0], sorted[i][1]});
        }
    }
    return merged.toArray(new int[0][]);
}

