static List<List<Integer>> subsets(int[] nums) {
    List<List<Integer>> out = new ArrayList<>();
    subsetsBacktrack(nums, 0, new ArrayList<>(), out);
    return out;
}

private static void subsetsBacktrack(int[] nums, int start,
                                     List<Integer> path, List<List<Integer>> out) {
    out.add(new ArrayList<>(path));                 // copy! path is mutated
    for (int i = start; i < nums.length; i++) {
        path.add(nums[i]);
        subsetsBacktrack(nums, i + 1, path, out);
        path.remove(path.size() - 1);
    }
}

static List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> out = new ArrayList<>();
    permuteBacktrack(nums, new boolean[nums.length], new ArrayList<>(), out);
    return out;
}

private static void permuteBacktrack(int[] nums, boolean[] used,
                                     List<Integer> path, List<List<Integer>> out) {
    if (path.size() == nums.length) {
        out.add(new ArrayList<>(path));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) continue;
        used[i] = true;
        path.add(nums[i]);
        permuteBacktrack(nums, used, path, out);
        path.remove(path.size() - 1);
        used[i] = false;
    }
}

static long fibMemo(int n) {
    long[] memo = new long[n + 1];
    Arrays.fill(memo, -1);
    return fibHelper(n, memo);
}

private static long fibHelper(int k, long[] memo) {
    if (k < 2) return k;
    if (memo[k] >= 0) return memo[k];
    return memo[k] = fibHelper(k - 1, memo) + fibHelper(k - 2, memo);
}

