    check(!isPalindrome("race a car"), "isPalindrome no");
    check(isAnagram("listen", "silent"), "isAnagram");
    check(groupAnagrams(new String[]{"eat", "tea", "tan"}).toString()
            .equals("[[eat, tea], [tan]]"), "groupAnagrams");
    check(alphaCounts("abb")[1] == 2, "alphaCounts");
    check(reverse("abc").equals("cba"), "reverse");

    // --- arrays ---
    check(Arrays.equals(twoSumSorted(new int[]{2, 7, 11, 15}, 9), new int[]{0, 1}), "twoSumSorted");
    check(Arrays.equals(twoSum(new int[]{3, 2, 4}, 6), new int[]{1, 2}), "twoSum");
    check(maxSumWindow(new int[]{2, 1, 5, 1, 3, 2}, 3) == 9, "maxSumWindow");
    check(longestUniqueSubstring("abcabcbb") == 3, "longestUniqueSubstring");
    check(Arrays.equals(prefixSums(new int[]{1, 2, 3}), new int[]{0, 1, 3, 6}), "prefixSums");
    check(subarraySumEqualsK(new int[]{1, 1, 1}, 2) == 2, "subarraySumEqualsK");
    check(kadane(new int[]{-2, 1, -3, 4, -1, 2, 1, -5, 4}) == 6, "kadane");
    int[] toRev = {1, 2, 3, 4};
    reverseRange(toRev, 0, 3);
    check(Arrays.equals(toRev, new int[]{4, 3, 2, 1}), "reverseRange");

    // --- hashing ---
    check(charFrequency("aab").get('a') == 2, "charFrequency");
    check(frequency(List.of("x", "x", "y")).get("x") == 2, "frequency");
    check(Arrays.equals(topKFrequent(new int[]{1, 1, 1, 2, 2, 3}, 2), new int[]{1, 2}), "topKFrequent");
    check(hasDuplicate(new int[]{1, 2, 1}), "hasDuplicate");

    // --- binary search ---
    check(binarySearch(new int[]{1, 3, 5, 7}, 5) == 2, "binarySearch hit");
    check(binarySearch(new int[]{1, 3, 5, 7}, 4) == -1, "binarySearch miss");
    check(lowerBound(new int[]{1, 3, 3, 7}, 3) == 1, "lowerBound");
    check(upperBound(new int[]{1, 3, 3, 7}, 3) == 3, "upperBound");
    check(binarySearchAnswer(0, 100, x -> x * x >= 50) == 8, "binarySearchAnswer");
    int[][] pairs = {{1, 2}, {1, 5}, {0, 9}};
    sortByCustom(pairs);
    check(Arrays.deepToString(pairs).equals("[[0, 9], [1, 5], [1, 2]]"), "sortByCustom");

    // --- stack / heap ---
    check(validParentheses("({[]})"), "validParentheses yes");
    check(!validParentheses("(]"), "validParentheses no");
    check(Arrays.equals(nextGreater(new int[]{2, 1, 3}), new int[]{3, 3, -1}), "nextGreater");
    check(Arrays.equals(kLargest(new int[]{5, 1, 9, 3}, 2), new int[]{9, 5}), "kLargest");

    // --- linked list ---
    check(Arrays.equals(toArray(reverseList(buildList(new int[]{1, 2, 3, 4}))),
            new int[]{4, 3, 2, 1}), "reverseList");
    check(middleNode(buildList(new int[]{1, 2, 3, 4, 5})).val == 3, "middleNode");
    check(!hasCycle(buildList(new int[]{1, 2, 3})), "hasCycle");
    check(Arrays.equals(toArray(mergeSorted(buildList(new int[]{1, 4}), buildList(new int[]{2, 3}))),
            new int[]{1, 2, 3, 4}), "mergeSorted");

    // --- trees ---
    TreeNode root = buildTree(new Integer[]{3, 9, 20, null, null, 15, 7});
    check(inorder(root).equals(List.of(9, 3, 15, 20, 7)), "inorder");
    check(inorderIterative(root).equals(inorder(root)), "inorderIterative");
    check(levelOrder(root).toString().equals("[[3], [9, 20], [15, 7]]"), "levelOrder");
    check(maxDepth(root) == 3, "maxDepth");
    TreeNode bst = buildTree(new Integer[]{5, 3, 8});
    check(bstContains(bst, 8) && !bstContains(bst, 4), "bstContains");

    // --- graphs ---
    char[][] grid = {"110".toCharArray(), "110".toCharArray(), "001".toCharArray()};
    check(countIslands(grid) == 2, "countIslands");
    Map<Integer, List<Integer>> g = buildGraph(new int[][]{{1, 2}, {2, 3}, {1, 4}}, false);
    Map<Integer, Integer> dist = bfsShortest(g, 1);
    check(dist.get(1) == 0 && dist.get(2) == 1 && dist.get(4) == 1 && dist.get(3) == 2, "bfsShortest");
    List<Integer> dfs = new ArrayList<>(dfsIterative(g, 1));
    java.util.Collections.sort(dfs);
    check(dfs.equals(List.of(1, 2, 3, 4)), "dfsIterative");
    check(topoSort(4, new int[][]{{0, 1}, {1, 2}, {2, 3}}).equals(List.of(0, 1, 2, 3)), "topoSort");
    check(topoSort(2, new int[][]{{0, 1}, {1, 0}}).isEmpty(), "topoSort cycle");

    Map<Integer, List<int[]>> weighted = new HashMap<>();
    weighted.put(0, List.of(new int[]{1, 4}, new int[]{2, 1}));
    weighted.put(2, List.of(new int[]{1, 2}));
    Map<Integer, Integer> sp = dijkstra(weighted, 0);
    check(sp.get(0) == 0 && sp.get(2) == 1 && sp.get(1) == 3, "dijkstra");

    UnionFind uf = new UnionFind(5);
    uf.union(0, 1);
    uf.union(1, 2);
    check(uf.connected(0, 2) && !uf.connected(0, 3), "UnionFind connected");
    check(uf.components == 3, "UnionFind components");

    // --- intervals ---
    check(Arrays.deepToString(mergeIntervals(new int[][]{{1, 3}, {2, 6}, {8, 10}}))
            .equals("[[1, 6], [8, 10]]"), "mergeIntervals");
    check(overlaps(new int[]{1, 5}, new int[]{4, 8}), "overlaps");

    // --- math & bits ---
    check(gcd(12, 18) == 6, "gcd");
    check(lcm(4, 6) == 12, "lcm");
    check(sieve(10).equals(List.of(2, 3, 5, 7)), "sieve");
    check(countBits(7) == 3, "countBits");
    check(getBit(5, 0) == 1 && setBit(4, 0) == 5 && clearBit(5, 0) == 4, "bit ops");
    check(singleNumber(new int[]{4, 1, 2, 1, 2}) == 4, "singleNumber");

    // --- backtracking & dp ---
    check(subsets(new int[]{1, 2, 3}).size() == 8, "subsets");
    check(permute(new int[]{1, 2, 3}).size() == 6, "permute");
    check(fibMemo(30) == 832040L, "fibMemo");
    check(climbStairs(5) == 8, "climbStairs");
    check(coinChange(new int[]{1, 2, 5}, 11) == 3, "coinChange");
    check(coinChange(new int[]{2}, 3) == -1, "coinChange unreachable");
    check(lcs("abcde", "ace") == 3, "lcs");

    System.out.println("all " + checksRun + " checks passed");
}
